  let mockViewParameters;
  let superUpdateSVGPropertySpy;

  beforeEach(() => {
    mockViewParameters = {
      realScale: 2.0
    };

    inkDrawingOptions = new InkDrawingOptions(mockViewParameters);

    // Spy on the parent's updateSVGProperty method
    superUpdateSVGPropertySpy = jest.spyOn(
      Object.getPrototypeOf(Object.getPrototypeOf(inkDrawingOptions)), 
      "updateSVGProperty"
    ).mockImplementation(() => {});
  });

  afterEach(() => {
    jest.clearAllMocks();
  });

