    test("should call super.updateSVGProperty with original name and value when name is not stroke-width", () => {
      const name = "fill";
      const value = "red";

      inkDrawingOptions.updateSVGProperty(name, value);

      expect(superUpdateSVGPropertySpy).toHaveBeenCalledWith(name, value);
    });

    test("should multiply value by realScale when name is stroke-width and value is provided", () => {
      const name = "stroke-width";
      const value = 5;
      const expectedValue = value * mockViewParameters.realScale;

      inkDrawingOptions.updateSVGProperty(name, value);

      expect(superUpdateSVGPropertySpy).toHaveBeenCalledWith(name, expectedValue);
    });

