      // Set initial stroke-width value
      inkDrawingOptions["stroke-width"] = initialValue;

      inkDrawingOptions.updateSVGProperty(name, undefined);

      expect(superUpdateSVGPropertySpy).toHaveBeenCalledWith(name, expectedValue);
    });
  });
});

