      expect(result.text).toEqual(testData.text);
      expect(result.date).toBe(testData.date);
      expect(result.deleted).toBe(testData.deleted);
      expect(result.richText).toBe(testData.richText);
    });

    it('should return the default data structure when no modifications are made', () => {
      const result = comment.serialize();

      expect(result).toEqual({
        text: null,
        date: null,
        deleted: false,
        richText: null
      });
    });

