describe('watchObjectOrEmbed', () => {
  let element;

  beforeEach(() => {
    jest.clearAllMocks();
    // Reset document.body.childElementCount to default value
    global.document.body._childElementCount = 1;
    global.location.href = 'http://example.com/test.pdf';

    element = {
      tagName: 'EMBED',
      type: 'application/pdf',
      src: 'http://example.com/document.pdf',
      __I_saw_this_element: false,
      parentNode: null
    };
  });

  afterEach(() => {
    jest.restoreAllMocks();
  });

  it('should return early if mime type is not application/pdf', () => {
    element.type = 'image/png';
    watchObjectOrEmbed(element);
    expect(mockUpdateEmbedElement).not.toHaveBeenCalled();
  });

  it('should return early if no mime type and path does not end with .pdf', () => {
    element.type = '';
    element.src = 'http://example.com/document.jpg';
    watchObjectOrEmbed(element);
    expect(mockUpdateEmbedElement).not.toHaveBeenCalled();
  });

  it('should handle Chrome default PDF page case', () => {
    element.name = 'plugin';
    element.parentNode = global.document.body;
    global.document.body._childElementCount = 1;
    element.src = global.location.href;

    watchObjectOrEmbed(element);
    expect(mockUpdateEmbedElement).not.toHaveBeenCalled();
  });

  it('should handle about:blank src case', () => {
    element.src = 'about:blank';
    watchObjectOrEmbed(element);
    expect(mockUpdateEmbedElement).not.toHaveBeenCalled();
  });

  it('should return early if element was already processed', () => {
    element.__I_saw_this_element = true;
    watchObjectOrEmbed(element);
    expect(mockUpdateEmbedElement).not.toHaveBeenCalled();
  });

  it('should process EMBED element correctly', () => {
    watchObjectOrEmbed(element);
    expect(mockUpdateEmbedElement).toHaveBeenCalledWith(element);
    expect(element.__I_saw_this_element).toBe(true);
  });

  it('should process OBJECT element correctly', () => {
    element.tagName = 'OBJECT';
    element.data = element.src;
    delete element.src;
    element.type = 'application/pdf';

    watchObjectOrEmbed(element);
    expect(mockUpdateObjectElement).toHaveBeenCalledWith(element);
    expect(element.__I_saw_this_element).toBe(true);
  });

  it('should not process unsupported element types', () => {
    element.tagName = 'IFRAME';
    watchObjectOrEmbed(element);
    expect(mockUpdateEmbedElement).not.toHaveBeenCalled();
    expect(mockUpdateObjectElement).not.toHaveBeenCalled();
  });

  it('should create MutationObserver to watch attribute changes', () => {
    const originalMutationObserver = global.MutationObserver;
    const mockObserve = jest.fn();

    global.MutationObserver = jest.fn().mockImplementation((callback) => {
      return {
        observe: mockObserve,
        callback: callback
      };
    });

    watchObjectOrEmbed(element);

    expect(global.MutationObserver).toHaveBeenCalled();
    expect(mockObserve).toHaveBeenCalledWith(element, {
      attributes: true,
      childList: false,
      characterData: false,
      attributeFilter: ['src']
    });

    global.MutationObserver = originalMutationObserver;
  });

  it('should use data attribute for OBJECT elements', () => {
    element.tagName = 'OBJECT';
    element.data = 'http://example.com/document.pdf';
    delete element.src;

    watchObjectOrEmbed(element);
    expect(mockUpdateObjectElement).toHaveBeenCalledWith(element);
  });

  it('should not call update function if src has not changed', () => {
    // First call
    watchObjectOrEmbed(element);
    expect(mockUpdateEmbedElement).toHaveBeenCalledTimes(1);

    // Reset mock to test subsequent calls
    mockUpdateEmbedElement.mockClear();

    // Second call with same src - should not trigger update
    watchObjectOrEmbed(element);
    expect(mockUpdateEmbedElement).not.toHaveBeenCalled();
  });
});

