      expect(hasher.h1).toBeDefined();
      expect(hasher.h2).toBeDefined();
    });

    it('should process Int8Array input', () => {
      const data = new Int8Array([1, 2, 3, 4, 5]);
      hasher.update(data);
      expect(hasher.h1).toBeDefined();
      expect(hasher.h2).toBeDefined();
    });

    it('should throw error for invalid input type', () => {
      expect(() => {
        hasher.update(123);
      }).toThrow('Invalid data format, must be a string or TypedArray.');

      expect(() => {
        hasher.update({});
      }).toThrow('Invalid data format, must be a string or TypedArray.');

      expect(() => {
