      const data = new Uint8Array([]);
      hasher.update(data);
      // For empty input, we just check that the method executes without error
      expect(hasher.h1).toBeDefined();
      expect(hasher.h2).toBeDefined();
    });

    it('should produce different hashes for different inputs', () => {
      const hasher1 = new MurmurHash3_64(0);
      const hasher2 = new MurmurHash3_64(0);

      hasher1.update('hello');
      hasher2.update('world');

      expect(hasher1.h1).not.toBe(hasher2.h1);
      expect(hasher1.h2).not.toBe(hasher2.h2);
    });

    it('should handle various tail lengths correctly', () => {
      // Test inputs that result in different tail lengths (1, 2, 3 bytes)
      const inputs = ['a', 'ab', 'abc', 'abcd'];

      inputs.forEach(input => {
        const hasher = new MurmurHash3_64(0);
        hasher.update(input);
        expect(hasher.h1).toBeDefined();
        expect(hasher.h2).toBeDefined();
      });
    });

    it('should maintain state between multiple updates', () => {
      hasher.update('hello');
      const h1AfterFirst = hasher.h1;
      const h2AfterFirst = hasher.h2;

      hasher.update('world');
      expect(hasher.h1).not.toBe(h1AfterFirst);
      expect(hasher.h2).not.toBe(h2AfterFirst);
    });

    it('should produce consistent results for same input', () => {
      const hasher1 = new MurmurHash3_64(0);
      const hasher2 = new MurmurHash3_64(0);

      hasher1.update('test string');
      hasher2.update('test string');

      expect(hasher1.h1).toBe(hasher2.h1);
      expect(hasher1.h2).toBe(hasher2.h2);
    });

    it('should handle longer string input', () => {
      hasher.update('this is a longer test string for hashing');
      expect(hasher.h1).toBeDefined();
      expect(hasher.h2).toBeDefined();
    });

    it('should handle buffer with exact 4-byte blocks', () => {
      const data = new Uint8Array([1, 2, 3, 4, 5, 6, 7, 8]);
      hasher.update(data);
      expect(hasher.h1).toBeDefined();
      expect(hasher.h2).toBeDefined();
    });
  });
});

