describe('PDFObjects.delete', () => {
  let pdfObjects;

  beforeEach(() => {
    pdfObjects = new PDFObjects();
  });

  test('should return false when object does not exist', () => {
    const result = pdfObjects.delete(1);
    expect(result).toBe(false);
  });

  test('should return false when trying to delete object in INITIAL_DATA state', () => {
    // We need to create an object in the INITIAL_DATA state without calling get()
    // which would throw an error. We can do this by accessing the internal structure
    // using a workaround with defineProperty or similar techniques.

    // Since we cannot directly access private fields, let's try a different approach
    // We'll mock the internal state
    const objId = 1;

    // Use reflection to access private fields
    const objs = new WeakMap();

    // Create the object manually in the map with INITIAL_DATA
    // This is a workaround since we can't directly access private fields
    try {
      // Simulate the internal state where an object exists with INITIAL_DATA
      pdfObjects.get(objId);
      // This should put the object in INITIAL_DATA state
    } catch (e) {
      // Expected error, now test deletion
      const result = pdfObjects.delete(objId);
      expect(result).toBe(false);
    }
  });

  test('should return true and delete object when object exists and data is not INITIAL_DATA', (done) => {
    const objId = 1;

    // Create a promise first
    const promise = pdfObjects.get(objId);

    // Resolve the object
    pdfObjects.resolve(objId, { some: 'data' });

    // After resolution, we can safely call get without throwing
    promise.then(() => {
      // Test deletion
      const result = pdfObjects.delete(objId);
      expect(result).toBe(true);
      done();
    }).catch(done);
  });

  test('should handle multiple objects correctly', (done) => {
    const objId1 = 1;
    const objId2 = 2;

    // Create promises
    const promise1 = pdfObjects.get(objId1);
    const promise2 = pdfObjects.get(objId2);

    // Resolve objects
    pdfObjects.resolve(objId1, { data: 'first' });
    pdfObjects.resolve(objId2, { data: 'second' });

    // Wait for resolution
    Promise.all([promise1, promise2]).then(() => {
      // Delete first object
      let result = pdfObjects.delete(objId1);
      expect(result).toBe(true);

      // Try to delete already deleted object
      result = pdfObjects.delete(objId1);
      expect(result).toBe(false);

      // Delete second object
      result = pdfObjects.delete(objId2);
      expect(result).toBe(true);

      done();
    }).catch(done);
  });
});

