import { Doc } from "../../../src/scripting_api/doc.js";

describe("Doc.print", () => {
  let doc;
  let mockSend;

  beforeEach(() => {
    // Create a Doc instance with minimal required data
    const testData = {
      baseURL: "http://example.com",
      metadata: "test metadata",
      numPages: 10,
      pageNum: 1
    };

    doc = new Doc(testData);

    // Mock the _send method to capture calls
    mockSend = jest.fn();
    doc._send = mockSend;

    // Enable printing by default
    doc._disablePrinting = false;
    doc._userActivation = true;
  });

  afterEach(() => {
    jest.clearAllMocks();
  });

  test("should not print when printing is disabled", () => {
    doc._disablePrinting = true;

    doc.print();

    expect(mockSend).not.toHaveBeenCalled();
    expect(doc._userActivation).toBe(true);
  });

  test("should not print when user activation is false", () => {
    doc._userActivation = false;

    doc.print();

    expect(mockSend).not.toHaveBeenCalled();
    expect(doc._userActivation).toBe(false);
  });

  test("should reset user activation after printing", () => {
    doc.print();

    expect(doc._userActivation).toBe(false);
  });

  test("should call _send with default parameters", () => {
    doc.print();

    expect(mockSend).toHaveBeenCalledWith({
      command: "print",
      start: 0,
      end: 0
    });
  });

  test("should handle object parameter correctly", () => {
    const printOptions = {
      bUI: true,
      nStart: 2,
      nEnd: 5,
      bSilent: true,
      bShrinkToFit: true,
      bPrintAsImage: true,
      bReverse: true,
      bAnnotations: false,
      printParams: null
    };

    doc.print(printOptions);

    expect(mockSend).toHaveBeenCalledWith({
      command: "print",
      start: 2,
      end: 5
    });
  });

  test("should use printParams for page range", () => {
    const printParams = {
      firstPage: 3,
      lastPage: 7
    };

    doc.print(true, 1, 2, false, false, false, false, true, printParams);

    expect(mockSend).toHaveBeenCalledWith({
      command: "print",
      start: 3,
      end: 7
    });
  });

  test("should handle negative nEnd value", () => {
    doc.print(true, 1, -1);

    expect(mockSend).toHaveBeenCalledWith({
      command: "print",
      start: 1,
      end: 0
    });
  });

  test("should truncate decimal page numbers", () => {
    doc.print(true, 1.7, 5.9);

    expect(mockSend).toHaveBeenCalledWith({
      command: "print",
      start: 1,
      end: 5
    });
  });

  test("should ensure page numbers are not negative", () => {
    doc.print(true, -2, -1);

    expect(mockSend).toHaveBeenCalledWith({
      command: "print",
      start: 0,
      end: 0
    });
  });

  test("should handle non-numeric parameters gracefully", () => {
    doc.print(true, "invalid", "alsoInvalid");

    expect(mockSend).toHaveBeenCalledWith({
      command: "print",
      start: 0,
      end: 0
    });
  });

  test("should prioritize printParams over direct parameters", () => {
    const printParams = {
      firstPage: 10,
      lastPage: 15
    };

    doc.print(true, 2, 3, false, false, false, false, true, printParams);

    expect(mockSend).toHaveBeenCalledWith({
      command: "print",
      start: 10,
      end: 15
    });
  });
});

