      cache: "no-store",
    });
  });

  test('should call chrome.storage.local.get with correct parameters', () => {
    global.chrome.storage.local.get.mockImplementation((storage, callback) => {
      callback({});
    });

    doSendPing();

    expect(global.chrome.storage.local.get).toHaveBeenCalledWith(global.localStorage, expect.any(Function));
