import { convertBlackAndWhiteToRGBA } from "../../../src/shared/image_utils.js";

// Mock FeatureTest manually since we can't import it
global.FeatureTest = {
  isLittleEndian: true
};

describe("convertBlackAndWhiteToRGBA", () => {
  beforeEach(() => {
    global.FeatureTest.isLittleEndian = true;
  });

  it("should convert black and white image data to RGBA with default parameters", () => {
    const src = new Uint8Array([0b10101010, 0b01010101]);
    const dest = new Uint8Array(64); // 16 * 4 bytes per uint32
    const result = convertBlackAndWhiteToRGBA({
      src,
      dest,
      width: 16,
      height: 1
    });

    expect(result.srcPos).toBe(2);
    expect(result.destPos).toBe(16);

    const destView = new Uint32Array(dest.buffer);
    // Based on the function logic, 1 maps to black (0xff000000) and 0 maps to white (0xffffffff)
    expect(destView[0]).toBe(0xff000000);  // First bit is 1 -> black
    expect(destView[1]).toBe(0xffffffff);  // Second bit is 0 -> white
  });

  it("should handle inverse decode correctly", () => {
    const src = new Uint8Array([0b11110000]);
    const dest = new Uint8Array(32); // 8 * 4 bytes per uint32
    const nonBlackColor = 0xff000000;
    const result = convertBlackAndWhiteToRGBA({
      src,
      dest,
      width: 8,
      height: 1,
      nonBlackColor,
      inverseDecode: true
    });

    const expectedDest = new Uint32Array(dest.buffer);
    // With inverseDecode=true, 1 maps to black and 0 maps to nonBlackColor
    expect(expectedDest[0]).toBe(0xff000000); // 1 -> black
    expect(expectedDest[1]).toBe(0xff000000); // 1 -> black
    expect(expectedDest[2]).toBe(0xff000000); // 1 -> black
    expect(expectedDest[3]).toBe(0xff000000); // 1 -> black
    expect(expectedDest[4]).toBe(nonBlackColor); // 0 -> nonBlackColor
    expect(expectedDest[5]).toBe(nonBlackColor); // 0 -> nonBlackColor
    expect(expectedDest[6]).toBe(nonBlackColor); // 0 -> nonBlackColor
    expect(expectedDest[7]).toBe(nonBlackColor); // 0 -> nonBlackColor
    expect(result.srcPos).toBe(1);
    expect(result.destPos).toBe(8);
  });

  it("should handle width remainder correctly", () => {
    const src = new Uint8Array([0b11000000]);
    const dest = new Uint8Array(12); // 3 * 4 bytes per uint32
    const result = convertBlackAndWhiteToRGBA({
      src,
      dest,
      width: 3,
      height: 1
    });

    const expectedDest = new Uint32Array(dest.buffer);
    expect(expectedDest[0]).toBe(0xff000000); // First bit is 1 -> black
    expect(expectedDest[1]).toBe(0xff000000); // Second bit is 1 -> black
    expect(expectedDest[2]).toBe(0xffffffff); // Third bit is 0 -> white
    expect(result.srcPos).toBe(1);
    expect(result.destPos).toBe(3);
  });

  it("should handle big endian correctly", () => {
    global.FeatureTest.isLittleEndian = false;
    const src = new Uint8Array([0b10000000]);
    const dest = new Uint8Array(4); // 1 * 4 bytes per uint32
    const result = convertBlackAndWhiteToRGBA({
      src,
      dest,
      width: 1,
      height: 1
    });

    const expectedDest = new Uint32Array(dest.buffer);
    // In big endian, black is 0x000000ff
    expect(expectedDest[0]).toBe(0x000000ff);
    expect(result.srcPos).toBe(1);
    expect(result.destPos).toBe(1);
  });

  it("should use default value when src position exceeds src length", () => {
    const src = new Uint8Array([0b10000000]);
    const dest = new Uint8Array(8); // 2 * 4 bytes per uint32
    const result = convertBlackAndWhiteToRGBA({
      src,
      srcPos: 2,
      dest,
      width: 2,
      height: 1
    });

    const expectedDest = new Uint32Array(dest.buffer);
    // When srcPos >= src.length, default value 255 (0b11111111) is used
    // All bits are 1, so they map to black (0xff000000)
    expect(expectedDest[0]).toBe(0xff000000);
    expect(expectedDest[1]).toBe(0xff000000);
    expect(result.srcPos).toBe(3);
    expect(result.destPos).toBe(2);
  });

  it("should process multiple rows correctly", () => {
    const src = new Uint8Array([0b11000000, 0b00110000]);
    const dest = new Uint8Array(64); // 16 * 4 bytes per uint32
    const result = convertBlackAndWhiteToRGBA({
      src,
      dest,
      width: 8,
      height: 2
    });

    expect(result.srcPos).toBe(2);
    expect(result.destPos).toBe(16);

    const destView = new Uint32Array(dest.buffer);
    // First row: 0b11000000
    expect(destView[0]).toBe(0xff000000); // bit 1 -> black
    expect(destView[1]).toBe(0xff000000); // bit 1 -> black
    expect(destView[2]).toBe(0xffffffff); // bit 0 -> white
    expect(destView[3]).toBe(0xffffffff); // bit 0 -> white

    // Second row: 0b00110000
    expect(destView[8]).toBe(0xffffffff);  // bit 0 -> white
    expect(destView[9]).toBe(0xffffffff);  // bit 0 -> white
    expect(destView[10]).toBe(0xff000000); // bit 1 -> black
    expect(destView[11]).toBe(0xff000000); // bit 1 -> black
  });
});

