import { BaseStandardFontDataFactory } from "../../../src/display/standard_fontdata_factory.js";

class MockStandardFontDataFactory extends BaseStandardFontDataFactory {
  constructor({ baseUrl = null }) {
    super({ baseUrl });
  }

  async _fetch(url) {
    if (url.includes("valid-font")) {
      return Promise.resolve(new Uint8Array([1, 2, 3]));
    } else {
      return Promise.reject(new Error("Network error"));
    }
  }
}

describe("BaseStandardFontDataFactory", () => {
  describe("fetch", () => {
    it("should throw an error when baseUrl is not provided", async () => {
      const factory = new MockStandardFontDataFactory({ baseUrl: null });

      await expect(factory.fetch({ filename: "font.ttf" }))
        .rejects
        .toThrow("Ensure that the `standardFontDataUrl` API parameter is provided.");
    });

    it("should throw an error when filename is not provided", async () => {
      const factory = new MockStandardFontDataFactory({ baseUrl: "https://example.com/fonts/" });

      await expect(factory.fetch({ filename: "" }))
        .rejects
        .toThrow("Font filename must be specified.");

      await expect(factory.fetch({}))
        .rejects
        .toThrow("Font filename must be specified.");
    });

    it("should construct the correct URL and call _fetch", async () => {
      const baseUrl = "https://example.com/fonts/";
      const filename = "valid-font.ttf";
      const factory = new MockStandardFontDataFactory({ baseUrl });

      const result = await factory.fetch({ filename });

      expect(result).toEqual(new Uint8Array([1, 2, 3]));
    });

    it("should throw a custom error when _fetch fails", async () => {
      const baseUrl = "https://example.com/fonts/";
      const filename = "error-font.ttf";
      const factory = new MockStandardFontDataFactory({ baseUrl });

      await expect(factory.fetch({ filename }))
        .rejects
        .toThrow(`Unable to load font data at: ${baseUrl}${filename}`);
    });
  });
});

