    jest.spyOn(mockStream, 'getByte').mockImplementation(() => {
      if (callCount < data.length) {
        return data[callCount++];
      }
      return -1; // EOF
    });

    const ascii85Stream = new Ascii85Stream(mockStream);
    ascii85Stream.ensureBuffer = jest.fn().mockImplementation((size) => {
      ascii85Stream.buffer = new Uint8Array(size);
      return ascii85Stream.buffer;
    });

    ascii85Stream.readBlock();

    expect(ascii85Stream.bufferLength).toBe(4);
    expect(ascii85Stream.buffer.slice(0, 4)).toEqual(new Uint8Array([0, 0, 0, 0]));
  });

  test('should handle partial ending', () => {
    isWhiteSpaceMock.mockImplementation((char) => {
      return char === 0x20 || char === 0x09 || char === 0x0a || char === 0x0d;
    });

    // Incomplete ASCII85 sequence
    const encodedData = new Uint8Array([0x36, 0x5a, 0x55]); // Partial sequence
    const mockStream = new Stream(encodedData);

    let callCount = 0;
    jest.spyOn(mockStream, 'getByte').mockImplementation(() => {
      if (callCount < encodedData.length) {
        return encodedData[callCount++];
      }
      return -1; // EOF
    });

    const ascii85Stream = new Ascii85Stream(mockStream);
    ascii85Stream.ensureBuffer = jest.fn().mockImplementation((size) => {
      ascii85Stream.buffer = new Uint8Array(size);
      return ascii85Stream.buffer;
    });

    ascii85Stream.readBlock();

    expect(ascii85Stream.eof).toBe(true);
  });
});

