    pageView = {
      enableDetailCanvas: true,
      maxCanvasPixels: 1000000,
      enableOptimizedPartialRendering: false,
      detailView: null,
      _needsRestrictedScaling: true,
      updateVisibleArea: function(visibleArea) {
        if (this.enableDetailCanvas) {
          if (
            this._needsRestrictedScaling &&
            this.maxCanvasPixels > 0 &&
            visibleArea
          ) {
            this.detailView ??= new PDFPageDetailView({
              pageView: this,
              enableOptimizedPartialRendering: this.enableOptimizedPartialRendering,
            });
            this.detailView.update({ visibleArea });
          } else if (this.detailView) {
            this.detailView.reset();
            this.detailView = null;
          }
        }
      }
    };
  });

  afterEach(() => {
    jest.clearAllMocks();
  });

  test("should create detailView and call update when conditions are met", () => {
    const visibleArea = { top: 0, left: 0, bottom: 100, right: 100 };

    pageView.updateVisibleArea(visibleArea);

    expect(PDFPageDetailView).toHaveBeenCalledWith({
      pageView: pageView,
      enableOptimizedPartialRendering: false,
    });
    expect(pageView.detailView.update).toHaveBeenCalledWith({ visibleArea });
  });

  test("should not create detailView when enableDetailCanvas is false", () => {
    pageView.enableDetailCanvas = false;

    const visibleArea = { top: 0, left: 0, bottom: 100, right: 100 };

    pageView.updateVisibleArea(visibleArea);

    expect(PDFPageDetailView).not.toHaveBeenCalled();
    expect(pageView.detailView).toBeNull();
  });

  test("should not create detailView when _needsRestrictedScaling is false", () => {
    pageView._needsRestrictedScaling = false;

    const visibleArea = { top: 0, left: 0, bottom: 100, right: 100 };

    pageView.updateVisibleArea(visibleArea);

    expect(PDFPageDetailView).not.toHaveBeenCalled();
    expect(pageView.detailView).toBeNull();
  });

  test("should not create detailView when maxCanvasPixels is 0", () => {
    pageView.maxCanvasPixels = 0;

    const visibleArea = { top: 0, left: 0, bottom: 100, right: 100 };

    pageView.updateVisibleArea(visibleArea);

    expect(PDFPageDetailView).not.toHaveBeenCalled();
    expect(pageView.detailView).toBeNull();
  });

  test("should not create detailView when visibleArea is null", () => {
    pageView.updateVisibleArea(null);

    expect(PDFPageDetailView).not.toHaveBeenCalled();
    expect(pageView.detailView).toBeNull();
  });

  test("should reset and clear detailView when conditions are not met and detailView exists", () => {
    pageView._needsRestrictedScaling = false;
    const mockDetailView = {
      reset: jest.fn(),
    };
    pageView.detailView = mockDetailView;

    pageView.updateVisibleArea({ top: 0, left: 0, bottom: 100, right: 100 });

    expect(mockDetailView.reset).toHaveBeenCalled();
    expect(pageView.detailView).toBeNull();
  });

  test("should handle case when detailView already exists and conditions are met", () => {
    pageView._needsRestrictedScaling = true;
    const existingDetailView = {
      update: jest.fn(),
      reset: jest.fn(),
    };
    pageView.detailView = existingDetailView;

    const visibleArea = { top: 0, left: 0, bottom: 100, right: 100 };

    pageView.updateVisibleArea(visibleArea);

    expect(PDFPageDetailView).not.toHaveBeenCalled();
    expect(existingDetailView.update).toHaveBeenCalledWith({ visibleArea });
    expect(pageView.detailView).toBe(existingDetailView);
  });
});

