describe('computeLuminance', () => {
  test('should return x / 12.92 when x is less than or equal to 0.03928', () => {
    const input = 0.03928;
    const expected = input / 12.92;
    expect(displayUtils.computeLuminance(input)).toBeCloseTo(expected);
  });

  test('should return x / 12.92 when x is exactly 0.03928', () => {
    const input = 0.03928;
    const expected = input / 12.92;
    expect(displayUtils.computeLuminance(input)).toBeCloseTo(expected);
  });

  test('should return ((x + 0.055) / 1.055) ** 2.4 when x is greater than 0.03928', () => {
    const input = 0.03929;
    const expected = Math.pow((input + 0.055) / 1.055, 2.4);
    expect(displayUtils.computeLuminance(input)).toBeCloseTo(expected);
  });

  test('should handle edge case when x is 0', () => {
    const input = 0;
    const expected = 0;
    expect(displayUtils.computeLuminance(input)).toBeCloseTo(expected);
  });

  test('should handle small positive value below threshold', () => {
    const input = 0.01;
    const expected = input / 12.92;
    expect(displayUtils.computeLuminance(input)).toBeCloseTo(expected);
  });

  test('should handle larger values correctly', () => {
    const input = 1.0;
    const expected = Math.pow((input + 0.055) / 1.055, 2.4);
