import { GlobalImageCache } from "../../../src/core/image_utils.js";

describe("GlobalImageCache", () => {
  describe("shouldCache", () => {
    let globalImageCache;
    let ref1;
    let ref2;

    beforeEach(() => {
      globalImageCache = new GlobalImageCache();
      ref1 = { num: 1, gen: 0 };
      ref2 = { num: 2, gen: 0 };
    });

    test("should return false when page index set size is less than threshold", () => {
      // First addition
      const result1 = globalImageCache.shouldCache(ref1, 0);
      expect(result1).toBe(false);

      // Second addition, still below threshold (NUM_PAGES_THRESHOLD = 2)
      const result2 = globalImageCache.shouldCache(ref1, 1);
      expect(result2).toBe(true);
    });

    test("should return true when page index set size meets threshold", () => {
      globalImageCache.shouldCache(ref1, 0);
      const result = globalImageCache.shouldCache(ref1, 1);
      expect(result).toBe(true);
    });

    test("should return false when image cache has reached limit and ref is not in image cache", () => {
      // Fill the image cache to reach the limit
      for (let i = 0; i < GlobalImageCache.MIN_IMAGES_TO_CACHE; i++) {
        const ref = { num: 100 + i, gen: 0 };
        globalImageCache._imageCache.put(ref, {});
      }

      // Verify cache is at limit
      expect(globalImageCache._imageCache.size).toBe(GlobalImageCache.MIN_IMAGES_TO_CACHE);

      // Add refs to meet page threshold for a new ref
      globalImageCache.shouldCache(ref2, 0);
      const result = globalImageCache.shouldCache(ref2, 1);

      // Should return true because page threshold is met, even though cache limit is reached
      // The function only returns false if page threshold is met AND ref is not in image cache AND cache limit is reached
      expect(result).toBe(true);
    });

    test("should create new page index set when ref is not in cache", () => {
      const result = globalImageCache.shouldCache(ref1, 0);
      expect(result).toBe(false);
      expect(globalImageCache._refCache.get(ref1)).toBeDefined();
      expect(globalImageCache._refCache.get(ref1).size).toBe(1);
    });

    test("should add page index to existing page index set", () => {
      globalImageCache.shouldCache(ref1, 0);
      globalImageCache.shouldCache(ref1, 1);

      const pageIndexSet = globalImageCache._refCache.get(ref1);
      expect(pageIndexSet.size).toBe(2);
      expect(pageIndexSet.has(0)).toBe(true);
      expect(pageIndexSet.has(1)).toBe(true);
    });

    test("should return true when image cache already has the ref even if limit is reached", () => {
      // Fill the image cache to reach the limit
      for (let i = 0; i < GlobalImageCache.MIN_IMAGES_TO_CACHE; i++) {
        const ref = { num: 100 + i, gen: 0 };
        globalImageCache._imageCache.put(ref, {});
      }

      // Add our specific ref to image cache
      globalImageCache._imageCache.put(ref1, {});

      // Now it should return true because ref is already in image cache
      globalImageCache.shouldCache(ref1, 0);
      const result = globalImageCache.shouldCache(ref1, 1);
      expect(result).toBe(true);
    });
  });
});

