      viewport: {
        rotation: 0,
        rawDims: { pageWidth: 100, pageHeight: 100, pageX: 0, pageY: 0 }
      }
    };

    mockUIManager = {
      viewParameters: { rotation: 0 },
      currentLayer: { div: { focus: jest.fn() } }
    };

    mockDiv = document.createElement("div");
    mockDiv.classList.add("selectedEditor");

    mockResizersDiv = document.createElement("div");
    mockResizersDiv.classList.remove("hidden");

    mockEditToolbar = { hide: jest.fn() };
    mockAltText = { toggleAltTextBadge: jest.fn() };

    // Create a spy on the hideCommentPopup method
    const hideCommentPopupSpy = jest.fn();

    editor = Object.create(AnnotationEditor.prototype, {
      constructor: { value: AnnotationEditor }
    });

    editor.parent = mockParent;
    editor.id = "test-id";
    editor.name = "TestEditor";
    editor._uiManager = mockUIManager;
    editor.div = mockDiv;
    editor.isSelected = true;
    editor._editToolbar = mockEditToolbar;
    editor.hideCommentPopup = hideCommentPopupSpy;

    // Use defineProperty to set private fields
    Object.defineProperty(editor, '#resizersDiv', {
      value: mockResizersDiv,
      writable: true
    });

    Object.defineProperty(editor, '#altText', {
      value: mockAltText,
      writable: true
    });
  });

  afterEach(() => {
    jest.restoreAllMocks();
  });

  test("should unselect when editor is selected", () => {
    editor.unselect();

    expect(editor.isSelected).toBe(false);
    expect(mockResizersDiv.classList.contains("hidden")).toBe(true);
    expect(mockDiv.classList.contains("selectedEditor")).toBe(false);
    expect(mockEditToolbar.hide).toHaveBeenCalled();
    expect(mockAltText.toggleAltTextBadge).toHaveBeenCalledWith(true);
    expect(editor.hideCommentPopup).toHaveBeenCalled();
  });

  test("should not unselect when editor is not selected", () => {
    editor.isSelected = false;

    editor.unselect();

    expect(editor.isSelected).toBe(false);
    expect(mockResizersDiv.classList.contains("hidden")).toBe(false);
    expect(mockDiv.classList.contains("selectedEditor")).toBe(true);
    expect(mockEditToolbar.hide).not.toHaveBeenCalled();
