describe("MessageHandler.sendWithStream", () => {
  let messageHandler;
  let mockComObj;
  let mockPostMessage;
  let mockAddEventListener;

  beforeEach(() => {
    mockPostMessage = jest.fn();
    mockAddEventListener = jest.fn();

    mockComObj = {
      postMessage: mockPostMessage,
      addEventListener: mockAddEventListener,
    };

    messageHandler = new MessageHandler("source", "target", mockComObj);

    // Reset global mocks
    ReadableStream.mockClear();
  });

  afterEach(() => {
    jest.clearAllMocks();
  });

  it("should create a ReadableStream with correct parameters", () => {
    const actionName = "testAction";
    const data = { key: "value" };
    const queueingStrategy = { highWaterMark: 1 };
    const transfers = [new ArrayBuffer(8)];

    const stream = messageHandler.sendWithStream(
      actionName,
      data,
      queueingStrategy,
      transfers
    );

    expect(stream).toBeDefined();
    expect(ReadableStream).toHaveBeenCalledWith(
      expect.objectContaining({
        start: expect.any(Function),
        pull: expect.any(Function),
        cancel: expect.any(Function),
      }),
      queueingStrategy
    );
  });

  it("should post a message on stream start", async () => {
    const actionName = "testAction";
    const data = { key: "value" };

    messageHandler.sendWithStream(actionName, data);

    // Get the callbacks passed to ReadableStream constructor
    const streamCallbacks = ReadableStream.mock.calls[0][0];
    const controller = { desiredSize: null };

    // Call the start function
    await streamCallbacks.start(controller);

    expect(mockPostMessage).toHaveBeenCalledWith(
      {
        sourceName: "source",
        targetName: "target",
        action: actionName,
        streamId: 1,
        data,
        desiredSize: null,
      },
      undefined
    );

    expect(messageHandler.streamControllers[1]).toBeDefined();
    expect(messageHandler.streamControllers[1].controller).toBe(controller);
    expect(messageHandler.streamControllers[1].startCall).toBeDefined();
  });

  it("should handle stream pull correctly", () => {
    const actionName = "testAction";
    const data = { key: "value" };

    messageHandler.sendWithStream(actionName, data);

    // Get the callbacks passed to ReadableStream constructor
    const streamCallbacks = ReadableStream.mock.calls[0][0];
    const controller = { desiredSize: null };

    // First call start to initialize
    streamCallbacks.start(controller);

    // Then call pull
    streamCallbacks.pull(controller);

    expect(mockPostMessage).toHaveBeenCalledWith({
      sourceName: "source",
      targetName: "target",
      stream: StreamKind.PULL,
      streamId: 1,
      desiredSize: null,
    });

    expect(messageHandler.streamControllers[1].pullCall).toBeDefined();
  });

  it("should handle stream cancel correctly", () => {
    const actionName = "testAction";
    const data = { key: "value" };
    const reason = new Error("Cancel reason");

    messageHandler.sendWithStream(actionName, data);

    // Get the callbacks passed to ReadableStream constructor
    const streamCallbacks = ReadableStream.mock.calls[0][0];
    const controller = { desiredSize: null };

    // First call start to initialize
    streamCallbacks.start(controller);

    // Then call cancel
    streamCallbacks.cancel(reason);

    expect(mockPostMessage).toHaveBeenCalledWith({
      sourceName: "source",
      targetName: "target",
      stream: StreamKind.CANCEL,
      streamId: 1,
      reason: "Cancel reason",
    });

    expect(messageHandler.streamControllers[1].cancelCall).toBeDefined();
    expect(messageHandler.streamControllers[1].isClosed).toBe(true);
  });

  it("should reject cancel if reason is not an Error", () => {
    const actionName = "testAction";
    const data = { key: "value" };
    const invalidReason = "not an error";

    messageHandler.sendWithStream(actionName, data);

    // Get the callbacks passed to ReadableStream constructor
    const streamCallbacks = ReadableStream.mock.calls[0][0];
    const controller = { desiredSize: null };

    // First call start to initialize
    streamCallbacks.start(controller);

    // Expect cancel to throw
    expect(() => streamCallbacks.cancel(invalidReason)).toThrow(
      "cancel must have a valid reason"
    );
  });

  it("should increment streamId for each new stream", () => {
    const actionName = "testAction";
    const data = { key: "value" };

    messageHandler.sendWithStream(actionName, data);
    messageHandler.sendWithStream(actionName, data);

    // Get the callbacks for both streams
    const streamCallbacks1 = ReadableStream.mock.calls[0][0];
    const streamCallbacks2 = ReadableStream.mock.calls[1][0];
    const controller = { desiredSize: null };

    // Call start on both
    streamCallbacks1.start(controller);
    streamCallbacks2.start(controller);

    expect(mockPostMessage).toHaveBeenNthCalledWith(
      1,
      {
        sourceName: "source",
        targetName: "target",
        action: actionName,
        streamId: 1,
        data,
        desiredSize: null,
      },
      undefined
    );

    expect(mockPostMessage).toHaveBeenNthCalledWith(
