    // 1 - min(1, 0+0) = 1 - 0 = 1 for each component
    expect(result).toEqual([1, 1, 1]);
  });

  test('should convert CMYK [1, 1, 1, 0] to RGB [0, 0, 0]', () => {
    const result = ColorConverters.CMYK_rgb([1, 1, 1, 0]);
    // 1 - min(1, 1+0) = 1 - 1 = 0 for each component
    expect(result).toEqual([0, 0, 0]);
  });

  test('should convert CMYK [0.5, 0.5, 0.5, 0.5] correctly', () => {
    const result = ColorConverters.CMYK_rgb([0.5, 0.5, 0.5, 0.5]);
    // 1 - min(1, 0.5+0.5) = 1 - 1 = 0 for each component
    expect(result).toEqual([0, 0, 0]);
  });

  test('should handle values that exceed 1 by clamping', () => {
    const result = ColorConverters.CMYK_rgb([1, 1, 1, 1]);
    // 1 - min(1, 1+1) = 1 - 1 = 0 for each component
    expect(result).toEqual([0, 0, 0]);
  });

  test('should handle negative values properly', () => {
    const result = ColorConverters.CMYK_rgb([-0.5, -0.5, -0.5, 0]);
    // 1 - min(1, -0.5+0) = 1 - min(1, -0.5) = 1 - (-0.5) = 1.5
    // But min(1, -0.5) = -0.5, so 1 - (-0.5) = 1.5
    // Wait, that's wrong. min(1, -0.5) = -0.5, but we need to check the actual formula
    // Actually min(1, c+k) where c=-0.5, k=0 => min(1, -0.5) = -0.5
    // So 1 - (-0.5) = 1.5
    expect(result).toEqual([1.5, 1.5, 1.5]);
  });

  test('should convert CMYK [0.2, 0.4, 0.6, 0.1] correctly', () => {
    const result = ColorConverters.CMYK_rgb([0.2, 0.4, 0.6, 0.1]);
    // R: 1 - min(1, 0.2+0.1) = 1 - 0.3 = 0.7
    // G: 1 - min(1, 0.4+0.1) = 1 - 0.5 = 0.5
    // B: 1 - min(1, 0.6+0.1) = 1 - 0.7 = 0.3
    expect(result).toEqual([0.7, 0.5, 0.3]);
  });

  test('should use scaleAndClamp for each RGB component', () => {
    ColorConverters.CMYK_rgb([0.3, 0.4, 0.5, 0.2]);

    // Should call scaleAndClamp three times (once for each RGB component)
    expect(scaleAndClamp).toHaveBeenCalledTimes(3);

    // Check that the right values were passed to scaleAndClamp
    expect(scaleAndClamp).toHaveBeenNthCalledWith(1, 1 - Math.min(1, 0.3 + 0.2));
    expect(scaleAndClamp).toHaveBeenNthCalledWith(2, 1 - Math.min(1, 0.4 + 0.2));
