import { Sidebar } from "../../web/sidebar.js";

describe("Sidebar destroy", () => {
  let mockSidebar;
  let mockResizer;
  let mockToggleButton;
  let sidebarInstance;

  beforeEach(() => {
    mockSidebar = document.createElement("div");
    mockSidebar.style.setProperty("--sidebar-width", "200");
    mockSidebar.style.setProperty("--sidebar-min-width", "100");
    mockSidebar.style.setProperty("--sidebar-max-width", "400");

    mockResizer = document.createElement("div");
    mockToggleButton = document.createElement("button");

    sidebarInstance = new Sidebar(
      { sidebar: mockSidebar, resizer: mockResizer, toggleButton: mockToggleButton },
      true,
      false
    );
  });

  afterEach(() => {
    jest.clearAllMocks();
  });

  test("should disconnect and nullify resizeObserver when it exists", () => {
    // Setup: ensure resizeObserver exists
    const mockDisconnect = jest.fn();
    sidebarInstance["_resizeObserver"] = {
      disconnect: mockDisconnect,
    };

    // Call destroy
    sidebarInstance.destroy();

    // Verify disconnect was called
    expect(mockDisconnect).toHaveBeenCalled();
    // Verify resizeObserver is nullified
    expect(sidebarInstance["_resizeObserver"]).toBeNull();
  });

  test("should not throw error when resizeObserver is already null", () => {
    // Setup: ensure resizeObserver is null
    sidebarInstance["_resizeObserver"] = null;

    // Call destroy - should not throw
    expect(() => {
      sidebarInstance.destroy();
    }).not.toThrow();

    // Verify resizeObserver is still null
    expect(sidebarInstance["_resizeObserver"]).toBeNull();
  });

  test("should handle undefined resizeObserver gracefully", () => {
    // Setup: ensure resizeObserver is undefined
    delete sidebarInstance["_resizeObserver"];

    // Call destroy - should not throw
    expect(() => {
      sidebarInstance.destroy();
    }).not.toThrow();

    // Verify resizeObserver is now null
    expect(sidebarInstance["_resizeObserver"]).toBeNull();
  });
});

