    const lastSave = this.#savesStack.pop();
    if (lastSave !== undefined) {
      ensureDebugMetadata(this.#debugMetadata, opIdx)?.dependencies.add(
        lastSave
      );
      this.#bboxes[opIdx] = this.#bboxes[lastSave];
    }
    return this;
  }

